package com.bank.constructor.factory;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private final String type;
    private final BigDecimal balance;
    private final BigDecimal interestRate;
    private final BigDecimal minBalance;

    // PRIVATE constructor — forces use of factory methods
    private Account(String id, String type, BigDecimal bal, BigDecimal rate, BigDecimal minBal) {
        this.accountId = id;
        this.type = type;
        this.balance = bal;
        this.interestRate = rate;
        this.minBalance = minBal;
    }

    // FACTORY METHODS — named, clear, validated:
    public static Account createSavings(String id, BigDecimal balance) {
        if (balance.compareTo(new BigDecimal("1000")) < 0)
            throw new IllegalArgumentException("Savings min opening balance: Rs.1000");
        return new Account(id, "SAVINGS", balance, new BigDecimal("0.04"), new BigDecimal("1000"));
    }

    public static Account createCurrent(String id, BigDecimal balance) {
        return new Account(id, "CURRENT", balance, BigDecimal.ZERO, BigDecimal.ZERO);
    }

    public static Account createFixedDeposit(String id, BigDecimal amount, BigDecimal rate) {
        if (amount.compareTo(new BigDecimal("10000")) < 0)
            throw new IllegalArgumentException("FD minimum: Rs.10000");
        return new Account(id, "FD", amount, rate, amount);  // FD: minBalance = full amount
    }

    public String getAccountId() { return accountId; }
    public String getType() { return type; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getInterestRate() { return interestRate; }

    @Override
    public String toString() { return type + "[" + accountId + "] Rs." + balance + " @" + interestRate; }
}
