package com.bank.constructor.utility;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class FeeCalculator {

    private FeeCalculator() {
        throw new UnsupportedOperationException("Utility class!");
    }

    public static BigDecimal brokerage(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.001")).setScale(2, RoundingMode.HALF_UP);
    }

    public static BigDecimal gst(BigDecimal brokerage) {
        return brokerage.multiply(new BigDecimal("0.18")).setScale(2, RoundingMode.HALF_UP);
    }

    public static BigDecimal totalFees(BigDecimal amount) {
        BigDecimal brk = brokerage(amount);
        return brk.add(gst(brk));
    }
}
