// ─── File: src/test/java/com/bank/constructor/PrivateConstructorTest.java ───
package com.bank.constructor;

import com.bank.constructor.factory.Account;
import com.bank.constructor.singleton.RbiConnectionManager;
import com.bank.constructor.utility.FeeCalculator;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class PrivateConstructorTest {

    // ═══ SINGLETON: only ONE instance ═══
    @Test
    void singleton_sameInstance() {
        RbiConnectionManager mgr1 = RbiConnectionManager.getInstance();
        RbiConnectionManager mgr2 = RbiConnectionManager.getInstance();
        assertThat(mgr1).isSameAs(mgr2);  // SAME object!
    }

    @Test
    void singleton_sharedState() {
        RbiConnectionManager mgr = RbiConnectionManager.getInstance();
        mgr.sendReport("Report A");
        mgr.sendReport("Report B");
        assertThat(mgr.getReportCount()).isEqualTo(2);  // shared state — one instance
    }

    // ═══ FACTORY: named creation ═══
    @Test
    void factory_savingsWithValidation() {
        Account savings = Account.createSavings("SAV001", new BigDecimal("50000"));
        assertThat(savings.getType()).isEqualTo("SAVINGS");
        assertThat(savings.getInterestRate()).isEqualByComparingTo("0.04");
    }

    @Test
    void factory_savingsMinBalanceEnforced() {
        assertThatThrownBy(() -> Account.createSavings("SAV001", new BigDecimal("500")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("1000");
    }

    @Test
    void factory_fdMinAmountEnforced() {
        assertThatThrownBy(() -> Account.createFixedDeposit("FD001", new BigDecimal("5000"), new BigDecimal("0.07")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("10000");
    }

    @Test
    void factory_differentTypesFromSameClass() {
        Account savings = Account.createSavings("SAV001", new BigDecimal("50000"));
        Account current = Account.createCurrent("CUR001", new BigDecimal("500000"));
        Account fd = Account.createFixedDeposit("FD001", new BigDecimal("100000"), new BigDecimal("0.07"));

        assertThat(savings.getType()).isEqualTo("SAVINGS");
        assertThat(current.getType()).isEqualTo("CURRENT");
        assertThat(fd.getType()).isEqualTo("FD");
        // Clear, named, validated — better than new Account(..., ..., ..., ...)
    }

    // ═══ UTILITY: no instantiation ═══
    @Test
    void utility_staticMethodsWork() {
        BigDecimal fees = FeeCalculator.totalFees(new BigDecimal("100000"));
        assertThat(fees).isGreaterThan(BigDecimal.ZERO);
    }

    @Test
    void utility_cannotInstantiate() {
        assertThatThrownBy(() -> {
            var constructor = FeeCalculator.class.getDeclaredConstructor();
            constructor.setAccessible(true);
            constructor.newInstance();
        }).hasCauseInstanceOf(UnsupportedOperationException.class);
        // Even REFLECTION can't create an instance — throws exception!
    }
}
```
